'use strict';
$('start').onclick=start;$('pause').onclick=()=>state==='running'?pause():state==='paused'?start():null;$('cleanPause').onclick=$('pause').onclick;
addEventListener('keydown',e=>{if(state==='menu'&&(e.target?.tagName==='SELECT'||e.target?.tagName==='BUTTON'))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','Enter','Escape','KeyW','KeyA','KeyS','KeyD','KeyR','ShiftLeft','ShiftRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(['ArrowLeft','ArrowRight','KeyA','KeyD','Space'].includes(e.code))keys.add(e.code);if(e.code==='Space'&&state==='running')jumpQueued=true;if(e.code==='Enter'&&state!=='running')start();if(e.code==='Escape'){if(state==='running')pause();else if(state==='paused')start()}if(e.code==='KeyR'&&state!=='menu'){state='ready';start()}if(e.code==='Escape'&&state==='menu'){$('menuSkins').classList.add('menuHidden');$('menuHome').classList.remove('menuHidden')}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();jumpQueued=false;if(state==='running')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();jumpQueued=false;if(state==='running')pause();}});document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(k);if(k==='Space'&&state==='running')jumpQueued=true;b.classList.add('active')});for(let ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{keys.delete(k);b.classList.remove('active')})});
